package uk.ac.ravensbourne.casevault.web;

import static org.junit.jupiter.api.Assertions.*;
import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.authentication;
import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.csrf;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;
import java.util.*; import java.util.stream.Stream;
import org.junit.jupiter.api.*; import org.junit.jupiter.params.ParameterizedTest; import org.junit.jupiter.params.provider.MethodSource; import org.junit.jupiter.params.provider.Arguments;
import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.test.context.ActiveProfiles; import org.springframework.test.web.servlet.MockMvc;
import uk.ac.ravensbourne.casevault.domain.*; import uk.ac.ravensbourne.casevault.repository.*; import uk.ac.ravensbourne.casevault.security.UserPrincipal; import uk.ac.ravensbourne.casevault.service.CaseWorkflowService; import uk.ac.ravensbourne.casevault.web.dto.CaseMutationRequests;

/** HTTP-level BOLA/IDOR matrix. A denied object is deliberately a 404. */
@SpringBootTest @AutoConfigureMockMvc @ActiveProfiles("test") class AuthorisationHttpMatrixTest {
 @Autowired MockMvc mvc; @Autowired JdbcTemplate jdbc; @Autowired OrganisationRepository orgs; @Autowired UserAccountRepository users; @Autowired CaseRepository cases; @Autowired ReportRepository reports; @Autowired CaseWorkflowService workflow;
 Organisation a,b,internal; UserAccount clientA,clientB,analyst,manager,auditor; CaseRecord caseA,caseB; ReportRecord managerReport;
 @BeforeEach void data(){jdbc.update("DELETE FROM audit_events");jdbc.update("UPDATE audit_chain_head SET last_event_id=NULL,last_hash=NULL WHERE singleton=TRUE");reports.deleteAll();jdbc.update("DELETE FROM remediation_actions");jdbc.update("DELETE FROM case_notes");jdbc.update("DELETE FROM case_assignments");cases.deleteAll();users.deleteAll();orgs.deleteAll();a=orgs.save(new Organisation(UUID.randomUUID(),"Client A"));b=orgs.save(new Organisation(UUID.randomUUID(),"Client B"));internal=orgs.save(new Organisation(UUID.randomUUID(),"Internal"));clientA=save(a,"a@test",Role.CLIENT_USER);clientB=save(b,"b@test",Role.CLIENT_USER);analyst=save(internal,"analyst@test",Role.SECURITY_ANALYST);manager=save(internal,"manager@test",Role.CASE_MANAGER);auditor=save(internal,"auditor@test",Role.AUDITOR_ADMIN);caseA=cases.save(new CaseRecord(UUID.randomUUID(),a,"Case A title","Synthetic",Category.OTHER,Severity.LOW,clientA));caseB=cases.save(new CaseRecord(UUID.randomUUID(),b,"Case B title","Synthetic",Category.OTHER,Severity.LOW,clientB));jdbc.update("INSERT INTO case_assignments(id,case_id,organisation_id,analyst_id,assigned_by) VALUES(?,?,?,?,?)",UUID.randomUUID(),caseA.getId(),a.getId(),analyst.getId(),manager.getId());managerReport=reports.save(new ReportRecord(UUID.randomUUID(),caseA,a,manager));}
 UserAccount save(Organisation o,String e,Role r){return users.save(new UserAccount(UUID.randomUUID(),o,e,"hash",r));} UsernamePasswordAuthenticationToken auth(UserAccount u){var p=UserPrincipal.from(u);return UsernamePasswordAuthenticationToken.authenticated(p,null,p.getAuthorities());}
 static Stream<Arguments> viewMatrix(){return Stream.of(Arguments.of(Role.CLIENT_USER,"own",200),Arguments.of(Role.CLIENT_USER,"other",404),Arguments.of(Role.SECURITY_ANALYST,"assigned",200),Arguments.of(Role.SECURITY_ANALYST,"unassigned",404),Arguments.of(Role.CASE_MANAGER,"own",200),Arguments.of(Role.CASE_MANAGER,"other",200),Arguments.of(Role.AUDITOR_ADMIN,"own",404),Arguments.of(Role.AUDITOR_ADMIN,"other",404));}
 @ParameterizedTest(name="T-AUTHZ-001 {0} {1} -> {2}") @MethodSource("viewMatrix") void tAuthz001HttpViewMatrix(Role role,String scope,int expected) throws Exception {UserAccount actor=switch(role){case CLIENT_USER->clientA;case SECURITY_ANALYST->analyst;case CASE_MANAGER->manager;case AUDITOR_ADMIN->auditor;};CaseRecord target=switch(scope){case "other","unassigned"->caseB;default->caseA;};mvc.perform(get("/cases/{id}",target.getId()).with(authentication(auth(actor)))).andExpect(status().is(expected));}
 @Test void tAuthzIdor001ClientARequestsClientBCaseById() throws Exception {mvc.perform(get("/cases/{id}",caseB.getId()).with(authentication(auth(clientA)))).andExpect(status().isNotFound());assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM audit_events WHERE action='ACCESS_DENIED'",Integer.class));}
 @Test void tAuthzIdor002AnalystRequestsUnassignedCase() throws Exception {mvc.perform(get("/cases/{id}",caseB.getId()).with(authentication(auth(analyst)))).andExpect(status().isNotFound());}
 @Test void tAuthzIdor003AuditorRequestsCaseContent() throws Exception {mvc.perform(get("/cases/{id}",caseA.getId()).with(authentication(auth(auditor)))).andExpect(status().isNotFound());}
 @Test void tAuthzIdor004ManagerCannotApproveOwnReport() throws Exception {mvc.perform(post("/cases/{caseId}/reports/{reportId}/approve",caseA.getId(),managerReport.getId()).with(authentication(auth(manager))).with(csrf())).andExpect(status().isNotFound());}
 @Test void tAuthzIdor005RoleTamperingParameterIgnored() throws Exception {mvc.perform(get("/cases/{id}",caseB.getId()).param("role","CASE_MANAGER").with(authentication(auth(clientA)))).andExpect(status().isNotFound());assertEquals(Role.CLIENT_USER,users.findById(clientA.getId()).orElseThrow().getRole());}
 @Test void tAuthzIdor006DisabledUserRejected() throws Exception {clientA.disable();users.save(clientA);mvc.perform(get("/cases/{id}",caseA.getId()).with(authentication(auth(clientA))).session(new org.springframework.mock.web.MockHttpSession())).andExpect(status().is3xxRedirection());}
 @Test void tAuthzIdor007HttpMethodTamperingDenied() throws Exception {mvc.perform(put("/cases/{id}",caseA.getId()).with(authentication(auth(manager))).with(csrf())).andExpect(status().isMethodNotAllowed());}
 @Test void tAuthzAdmin001AdminRouteRequiresAuditorAtUrlAndMethod() throws Exception {mvc.perform(get("/admin/health").with(authentication(auth(manager)))).andExpect(status().isForbidden());mvc.perform(get("/admin/health").with(authentication(auth(auditor)))).andExpect(status().isOk());}
 @Test void tCase001ListIsTenantScopedAndCapsPagination(){assertEquals(1,workflow.search(UserPrincipal.from(clientA),"",null,null,null,null,0,500,"createdAt").getTotalElements());assertTrue(workflow.search(UserPrincipal.from(clientA),"",null,null,null,null,0,500,"createdAt").getSize()<=50);}
 @Test void tCase002AssignStatusNotesAndActions(){workflow.assign(UserPrincipal.from(manager),caseA.getId(),new CaseMutationRequests.Assign(analyst.getId()));workflow.status(UserPrincipal.from(manager),caseA.getId(),new CaseMutationRequests.Status(CaseStatus.TRIAGED));workflow.note(UserPrincipal.from(analyst),caseA.getId(),new CaseMutationRequests.Note("<script>alert(1)</script>",false));workflow.action(UserPrincipal.from(analyst),caseA.getId(),new CaseMutationRequests.Action("Synthetic action",RemediationStatus.OPEN));assertEquals(CaseStatus.TRIAGED,cases.findById(caseA.getId()).orElseThrow().getStatus());}
 @Test void tInj001AndTInj002SearchEscapesWildcardsAndWhitelistsSort(){assertEquals(0,workflow.search(UserPrincipal.from(clientA),"' OR 1=1 --%_",null,null,null,null,0,20,"not-a-field").getTotalElements());assertDoesNotThrow(()->workflow.search(UserPrincipal.from(clientA),"%",null,null,null,null,0,20,"not-a-field"));}
}
